#pragma once
static const GarminImage& zonar_image(const char* name,bool wide=false){return page_image(wide?std::string("copilot/westernstar/western_star_zonar_5700xe_")+std::string(name).substr(6):std::string("copilot/cascadia/icuc/")+name);}
static bool zonar_assets_ready(bool wide=false){for(const auto* f:{"zonar_home.dds","zonar_nav.dds","zonar_notrip.dds"})if(zonar_image(f,wide).pixels.empty())return false;return true;}
static std::string zonar_day_time(){const auto now=copilot_minutes();if(now<0)return "Week -- --- --:-- --";return "Week "+std::to_string(now/(7*1440)+1)+" "+copilot_weekday(now)+"  "+copilot_clock()+(now%1440<720?" AM":" PM");}
static std::string zonar_drive_remaining(){if(!g_tripPresent||!g_haveNavTime)return {};const auto seconds=g_navTimeSec.load();if(!std::isfinite(seconds)||seconds<0)return {};const auto minutes=int64_t(std::ceil(seconds/60));char text[32];std::snprintf(text,sizeof(text),"%lld:%02lld",minutes/60,minutes%60);return text;}
static int zonar_name_font(const std::string& name,int width){int font=44;while(font>14&&tomtom_measure(name,font)>width)--font;return font;}
static void zonar_home(std::vector<uint8_t>& pixels,const OverlaySettings& settings){const unsigned canvasHeight=settings.navplus==11?zonar5700Height:zonarHeight;
 pixels.assign(size_t(zonarWidth)*canvasHeight*4,0);const auto& home=zonar_image("zonar_home.dds",settings.navplus==11);overlay_blit(pixels,home.pixels,home.width,home.height,settings.items[1],zonarWidth,canvasHeight);
 auto text=[&](const std::string& value,unsigned item,int size,COLORREF color,int weight=FW_NORMAL){const auto p=settings.items[item];std::vector<uint8_t> layer(size_t(p.w)*p.h*4,0);garmin_text(layer,p.w,p.h,value,{0,0,p.w,p.h},size,color,weight);overlay_blit(pixels,layer,p.w,p.h,p,zonarWidth,canvasHeight);};
 int clockFont=20;while(clockFont>12&&tomtom_measure(zonar_day_time(),clockFont)>settings.items[8].w)--clockFont;text(zonar_day_time(),8,clockFont,RGB(225,225,225));
 std::string name=zonarProfileName;const int font=zonar_name_font(name,settings.items[13].w);while(!name.empty()&&tomtom_measure(name,font)>settings.items[13].w){size_t end=name.size()-1;while(end&&(static_cast<unsigned char>(name[end])&0xc0)==0x80)--end;name.resize(end);}if(name!=zonarProfileName&&!name.empty()){while(!name.empty()&&tomtom_measure(name+"...",font)>settings.items[13].w){size_t end=name.size()-1;while(end&&(static_cast<unsigned char>(name[end])&0xc0)==0x80)--end;name.resize(end);}name+="...";}text(name,13,font,RGB(225,225,225));
 text(zonarJobActive?"On Duty":"Off Duty",0,29,zonarJobActive?RGB(255,185,0):RGB(255,255,255));
 // A code-native seven-segment face matches the supplied blue digital readout
 // without installing a font or depending on another application's fonts.
 const auto remaining=zonar_drive_remaining();if(remaining.empty())return;constexpr int glyph=48,height=80,gap=7,stroke=8;std::vector<uint8_t> digital((glyph+gap)*remaining.size()*height*4,0);const int width=int((glyph+gap)*remaining.size());int x=0;const unsigned masks[]={0x3f,0x06,0x5b,0x4f,0x66,0x6d,0x7d,0x07,0x7f,0x6f};
 for(char c:remaining){if(c==':'){copilot_round(digital,width,height,{x+20,23,x+28,31},2,RGB(0,169,230));copilot_round(digital,width,height,{x+20,52,x+28,60},2,RGB(0,169,230));}else if(c>='0'&&c<='9'){const RECT segments[]={{x+stroke,0,x+glyph-stroke,stroke},{x+glyph-stroke,stroke,x+glyph,40-stroke/2},{x+glyph-stroke,40+stroke/2,x+glyph,72},{x+stroke,72,x+glyph-stroke,80},{x,40+stroke/2,x+stroke,72},{x,stroke,x+stroke,40-stroke/2},{x+stroke,36,x+glyph-stroke,44}};for(unsigned i=0;i<7;++i)if(masks[c-'0']&(1<<i))copilot_round(digital,width,height,segments[i],2,RGB(0,169,230));}x+=glyph+gap;}
 const auto p=settings.items[2];const double fit=std::min({1.,double(p.w)/width,double(p.h)/height});overlay_blit(pixels,digital,width,height,{p.x,p.y,int(std::lround(width*fit)),int(std::lround(height*fit))},zonarWidth,canvasHeight);
}
static void zonar_startup(std::vector<uint8_t>& pixels,const OverlaySettings& settings,int phase){const unsigned canvasHeight=settings.navplus==11?zonar5700Height:zonarHeight;
 pixels.assign(size_t(zonarWidth)*canvasHeight*4,20);for(size_t i=3;i<pixels.size();i+=4)pixels[i]=255;if(phase<zonarHoldMs)return;
 std::vector<uint8_t> home;zonar_home(home,settings);const unsigned alpha=unsigned(std::clamp(phase-zonarHoldMs,0,500))*255/500;for(size_t i=3;i<home.size();i+=4)home[i]=uint8_t(alpha);overlay_blit(pixels,home,zonarWidth,canvasHeight,{0,0,int(zonarWidth),int(canvasHeight)},zonarWidth,canvasHeight);
}
static void render_zonar(std::vector<uint8_t>& pixels,const OverlaySettings& settings,const bettergps_navigation::Display& guidance=bettergps_navigation::Current()){const unsigned canvasHeight=settings.navplus==11?zonar5700Height:zonarHeight;
 if(presentation_home(g_tripPresent.load())){zonar_home(pixels,settings);return;}const bool trip=g_tripPresent.load(),dark=presentation_dark();pixels.assign(size_t(zonarWidth)*canvasHeight*4,0);const auto& base=zonar_image(trip?"zonar_nav.dds":"zonar_notrip.dds",settings.navplus==11);overlay_blit(pixels,base.pixels,base.width,base.height,settings.items[trip?6:7],zonarWidth,canvasHeight);
 auto module=[&](unsigned item,const std::vector<uint8_t>& layer,unsigned w,unsigned h){overlay_blit(pixels,layer,w,h,settings.items[item],zonarWidth,canvasHeight);};module(14,copilot_speed_limit(dark),78,104);module(11,copilot_real_speed(dark),78,43);if(!trip)return;
 const auto p=guidance_presentation(guidance);module(3,copilot_maneuver(p),132,68);module(5,copilot_road(p,guidance),384,80);std::vector<uint8_t> distance(148*40*4,0),eta(144*40*4,0);garmin_text(distance,148,40,copilot_distance(),{4,0,144,40},34,copilotOrange,FW_BOLD,true);garmin_text(eta,144,40,copilot_eta(),{2,0,142,40},30,copilotOrange,FW_BOLD,true);module(9,distance,148,40);module(10,eta,144,40);
}
